<?php
declare(strict_types=1);
trait ContractOperations {
    public function tabletConnectionTest(string $draft):bool {
        $permit=json_decode($this->one("SELECT value FROM settings WHERE name='tablet_connection_test'")['value']??'{}',true);
        return ($permit['draft_id']??'')===$draft && (int)($permit['expires']??0)>time() && !($permit['used']??true);
    }
    private function sessionHash():string{return $this->vault->fingerprint('draft:'.session_id());}
    public function catalog():array{return ['tariffs'=>$this->sql('SELECT * FROM tariffs WHERE active=1 ORDER BY brand,name'),'legal'=>$this->sql('SELECT * FROM legal_versions WHERE active=1 ORDER BY created_at DESC'),'banking'=>['fitness'=>$this->bankingStatus('fitness'),'fighters'=>$this->bankingStatus('fighters')]];}
    public function newDraft(array $prefill=[]):array{$this->kiosk();return $this->transaction(function()use($prefill){$this->sql('DELETE FROM drafts WHERE session_hash=? OR expires_at<?',[$this->sessionHash(),instant()]);unset($_SESSION['receipt']);$id=uuid();$data=$prefill?:['personal'=>[],'brand'=>'fitness','payment_method'=>'cash','consents'=>['marketing'=>false]];$this->sql('INSERT INTO drafts(id,session_hash,data_enc,expires_at,updated_at) VALUES(?,?,?,?,?)',[$id,$this->sessionHash(),$this->seal($data),gmdate('Y-m-d\TH:i:s\Z',time()+1800),instant()]);$_SESSION['draft_id']=$id;$permit=json_decode($this->one("SELECT value FROM settings WHERE name='tablet_connection_test'")['value']??'{}',true);if(($permit['next_draft']??false)&&(int)($permit['expires']??0)>time()){$permit['draft_id']=$id;$permit['next_draft']=false;$this->sql("UPDATE settings SET value=? WHERE name='tablet_connection_test'",[jencode($permit)]);$this->audit($this->actor(),'TABLET_CONNECTION_TEST_BOUND',$id);}return ['id'=>$id,'data'=>$data];});}
    public function draft():array{$this->kiosk();$d=$this->one('SELECT * FROM drafts WHERE id=? AND session_hash=?',[$_SESSION['draft_id']??'',$this->sessionHash()]);ensure($d&&$d['expires_at']>instant(),'La sesión de alta ha caducado. Empieza una nueva.',410);return $d;}
    public function saveDraft(array $data):array{$d=$this->draft();if(isset($data['payment_method']))ensure(in_array($data['payment_method'],['cash','debit'],true),'Solo se admite efectivo o domiciliación bancaria.');foreach(['personal','bank','consents'] as $field)if(isset($data[$field]))ensure(is_array($data[$field]),'Revisa el formato del formulario.');foreach(['brand','tariff_id','payment_method'] as $field)if(isset($data[$field]))ensure(is_string($data[$field]),'Revisa el formato del formulario.');ensure(strlen(jencode($data))<24000,'Formulario demasiado grande.');$old=$this->open($d['data_enc']);$allowed=['personal','brand','tariff_id','payment_method','bank','consents'];$clean=[];foreach($allowed as $k)if(array_key_exists($k,$data))$clean[$k]=$data[$k];if(isset($clean['personal'])&&count($clean['personal']))$clean['personal']=validatePersonal($clean['personal']);if(($clean['payment_method']??'')==='debit'&&isset($clean['bank'])&&($clean['bank']['iban']??'')!=='')$clean['bank']=validateBank($clean['bank'],$clean['personal']??[]);foreach(['member_id','previous_id'] as $k)if(isset($old[$k]))$clean[$k]=$old[$k];$this->sql('UPDATE drafts SET data_enc=?,review_enc=NULL,review_hash=NULL,updated_at=?,expires_at=? WHERE id=?',[$this->seal($clean),instant(),gmdate('Y-m-d\TH:i:s\Z',time()+1800),$d['id']]);return ['saved'=>true];}
    public function prepareContract():array{$d=$this->draft();$data=$this->open($d['data_enc']);$connectionTest=$this->tabletConnectionTest($d['id']);$personal=validatePersonal($data['personal']??[]);$tariff=$this->one('SELECT * FROM tariffs WHERE id=? AND active=1',[$data['tariff_id']??'']);ensure($tariff,'Selecciona una tarifa activa.');ensure(($data['brand']??'')===$tariff['brand'],'La tarifa no corresponde al centro seleccionado.');$legal=$this->one('SELECT * FROM legal_versions WHERE brand=? AND active=1 ORDER BY created_at DESC LIMIT 1',[$tariff['brand']]);ensure($legal,'Faltan textos contractuales para esta marca.');
        $c=$data['consents']??[];ensure(($c['legal_id']??'')===$legal['id'],'Han cambiado los textos. Recarga y revisa las condiciones actuales.',409);ensure(($c['contract']??false)===true&&($c['privacy']??false)===true,'Acepta las condiciones y confirma que has leído la información de protección de datos.');$payment=$data['payment_method']??'';ensure(in_array($payment,['cash','debit'],true),'Selecciona la forma de pago.');$bank=null;$creditor=json_decode($this->one("SELECT value FROM settings WHERE name='creditor'")['value']??'{}',true);$creditor+=['name'=>'','id'=>''];
        if($payment==='debit'){if(!$this->demo()&&!$connectionTest){$status=$this->bankingStatus($tariff['brand']);ensure($status['ready'],$status['reason'],409);}$bank=validateBank($data['bank']??[],$personal);ensure(($c['sepa']??false)===true,'Confirma la autorización de domiciliación.');if(!$this->demo()&&!$connectionTest)ensure($creditor['name']!==''&&$creditor['id']!=='','Falta configurar el acreedor SEPA autorizado.',409);}
        $age=(new DateTimeImmutable($personal['birth_date']))->diff(new DateTimeImmutable(madridToday()))->y;
        $fp=$this->vault->fingerprint($personal['document_type'].':'.$personal['document']);$existing=$this->one('SELECT id FROM members WHERE document_fingerprint=?',[$fp]);ensure(!$existing||($data['member_id']??'')===$existing['id'],'Ya existe un socio con ese documento. Un trabajador debe crear una nueva versión del contrato.',409);
        $discount=(int)$d['discount_percent'];ensure($discount<=(int)$tariff['max_discount'],'El descuento debe ser revisado por un trabajador.');$monthly=intdiv((int)$tariff['monthly_cents']*(100-$discount)+50,100);$reference='TF-'.date('Y').'-'.strtoupper(substr($d['id'],0,12));
        // Primer mes proporcional (del día del alta a fin de mes) salvo en nuevas versiones de un contrato existente.
        $first=empty($data['previous_id'])?prorateMonth($monthly,madridToday()):null;$firstCents=$first?$first['cents']:$monthly;
        $snapshot=['paper_reference'=>paperReference($this->root),'member_number'=>isset($data['member_id'])?($this->one('SELECT innux_number FROM members WHERE id=?',[$data['member_id']])['innux_number']??null):null,'reference'=>$reference,'date_local'=>date('d-m-Y H:i'),'prepared_at'=>instant(),'personal'=>$personal,'tariff'=>$tariff,'legal'=>$legal,'discount_percent'=>$discount,'discount_reason'=>$d['discount_reason'],'discount_actor'=>$d['discount_actor'],'monthly_cents'=>$monthly,'enrollment_cents'=>(int)$tariff['enrollment_cents'],'first_month_cents'=>$firstCents,'first_month_from'=>$first?date('d-m-Y',strtotime($first['from'])):null,'first_month_to'=>$first?date('d-m-Y',strtotime($first['to'])):null,'initial_cents'=>$firstCents+(int)$tariff['enrollment_cents'],'payment_method'=>$payment,'bank'=>$bank,'creditor'=>$creditor,'mandate_reference'=>$payment==='debit'?'TF-M-'.strtoupper(substr($d['id'],0,20)):null,'consents'=>['legal_id'=>$legal['id'],'contract'=>true,'privacy'=>true,'sepa'=>$payment==='debit','marketing'=>($c['marketing']??false)===true],'tablet_connection_test'=>$connectionTest,'is_demo'=>$this->demo()||$connectionTest,'member_id'=>$data['member_id']??null,'previous_id'=>$data['previous_id']??null];
        $photo=$this->one('SELECT image_hash FROM draft_photos WHERE draft_id=?',[$d['id']]);$snapshot['photo_hash']=$photo['image_hash']??null;
        $hash=hash('sha256',jencode($snapshot));$this->sql('UPDATE drafts SET review_enc=?,review_hash=? WHERE id=?',[$this->seal($snapshot),$hash,$d['id']]);return ['review_hash'=>$hash,'summary'=>['reference'=>$reference,'monthly_cents'=>$monthly,'first_month_cents'=>$firstCents,'first_month_from'=>$snapshot['first_month_from'],'first_month_to'=>$snapshot['first_month_to'],'enrollment_cents'=>$snapshot['enrollment_cents'],'initial_cents'=>$snapshot['initial_cents'],'discount_percent'=>$discount,'holder_pending'=>$bank&&!$bank['holder_same'],'is_demo'=>$snapshot['is_demo']]];
    }
    public function previewPdf():string{$d=$this->draft();ensure($d['review_enc']!==null,'Revisa antes el contrato.');return (new ContractPdf($this->root,$this->config))->build($this->open($d['review_enc']),[],true);}
    public function signContract(array $request):array{$this->kiosk();ensure(($request['confirmed']??false)===true,'Confirma expresamente la firma.');$signature=validateSignature($request['signature']??null);$key=textField($request,'review_hash',64);return $this->transaction(function()use($signature,$key){$d=$this->draft();ensure($d['review_enc']!==null&&hash_equals((string)$d['review_hash'],$key),'El contrato ha cambiado. Revísalo antes de firmar.',409);$snapshot=$this->open($d['review_enc']);ensure(in_array($snapshot['payment_method']??'',['cash','debit'],true),'Selecciona efectivo o domiciliación y revisa de nuevo el contrato.',409);ensure(($snapshot['kind']??'contract')==='contract','Este documento no es un contrato de alta.',403);if(!$this->demo())ensure(!$snapshot['is_demo']||(($snapshot['tablet_connection_test']??false)&&$this->tabletConnectionTest($d['id'])),'No se admiten borradores demo en producción.');$pdf=(new ContractPdf($this->root,$this->config))->build($snapshot,$signature);$person=$snapshot['personal'];$member=$snapshot['member_id']?:uuid();$fingerprint=$this->vault->fingerprint($person['document_type'].':'.$person['document']);
        if(!$snapshot['member_id']){ensure(!$this->one('SELECT id FROM members WHERE document_fingerprint=?',[$fingerprint]),'Ya existe un socio con ese documento. Un trabajador debe crear una nueva versión del contrato.',409);$this->sql('INSERT INTO members(id,internal_reference,personal_enc,document_fingerprint,email_fingerprint,created_at) VALUES(?,?,?,?,?,?)',[$member,'TF-S-'.strtoupper(substr($member,0,12)),$this->seal($person),$fingerprint,$this->vault->fingerprint($person['email']),instant()]);}
        else{$existing=$this->one('SELECT id FROM members WHERE document_fingerprint=?',[$fingerprint]);ensure(!$existing||$existing['id']===$member,'Documento asociado a otro socio.',409);$this->sql('UPDATE members SET personal_enc=?,document_fingerprint=?,email_fingerprint=? WHERE id=?',[$this->seal($person),$fingerprint,$this->vault->fingerprint($person['email']),$member]);}
        if(!empty($snapshot['member_number']))$this->sql('UPDATE members SET innux_number=? WHERE id=? AND innux_number IS NULL',[$snapshot['member_number'],$member]);
        ensure(($snapshot['kind']??'contract')==='contract','El documento no es un contrato de alta.',403);$contract=uuid();$evidence=['signed_at'=>instant(),'review_hash'=>$key,'snapshot_hash'=>hash('sha256',jencode($snapshot)),'signature_hash'=>hash('sha256',jencode($signature)),'signature_method'=>'DRAWN_VISUAL_V1','explicit_confirmation'=>true,'qualified_signature'=>false,'legal_version'=>$snapshot['legal']['id'],'center_state'=>'PENDING_ACCEPTANCE'];
        $this->sql('INSERT INTO contracts(id,reference,member_id,tariff_id,snapshot_enc,snapshot_hash,pdf_enc,pdf_hash,signature_enc,evidence_enc,legal_id,payment_method,monthly_cents,enrollment_cents,initial_cents,created_at,is_demo,previous_id) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)',[$contract,$snapshot['reference'],$member,$snapshot['tariff']['id'],$this->seal($snapshot),hash('sha256',jencode($snapshot)),$this->vault->encrypt($pdf,'pdf'),hash('sha256',$pdf),$this->seal($signature,'signature'),$this->seal($evidence),$snapshot['legal']['id'],$snapshot['payment_method'],$snapshot['monthly_cents'],$snapshot['enrollment_cents'],$snapshot['initial_cents'],instant(),(int)$snapshot['is_demo'],$snapshot['previous_id']]);
        if($snapshot['bank']&&!($snapshot['tablet_connection_test']??false)){$bank=$snapshot['bank'];$this->sql('INSERT INTO mandates(id,reference,member_id,contract_id,bank_enc,last_four,state,holder_same,signed_at) VALUES(?,?,?,?,?,?,?,?,?)',[uuid(),$snapshot['mandate_reference'],$member,$contract,$this->seal($bank,'bank'),substr($bank['iban'],-4),$bank['holder_same']?'ACTIVE':'PENDING_HOLDER',(int)$bank['holder_same'],$bank['holder_same']?instant():null]);}
        $photo=$this->one('SELECT * FROM draft_photos WHERE draft_id=?',[$d['id']]);ensure(($snapshot['photo_hash']??null)===($photo['image_hash']??null),'La foto ha cambiado. Revisa de nuevo el contrato.',409);if($photo)$this->sql('INSERT INTO contract_photos(contract_id,image_enc,image_hash,width,height,created_at) VALUES(?,?,?,?,?,?)',[$contract,$photo['image_enc'],$photo['image_hash'],$photo['width'],$photo['height'],instant()]);
        if($snapshot['tablet_connection_test']??false){$this->sql("DELETE FROM settings WHERE name='tablet_connection_test'");$this->audit($this->actor(),'TABLET_CONNECTION_TEST_COMPLETED',$contract,['draft_id'=>$d['id'],'no_mandate'=>true]);}
        $this->audit($this->actor(),'CONTRACT_SIGNED',$contract,['snapshot_hash'=>$evidence['snapshot_hash'],'pdf_hash'=>hash('sha256',$pdf),'demo'=>$snapshot['is_demo']]);$this->sql('DELETE FROM drafts WHERE id=?',[$d['id']]);unset($_SESSION['draft_id']);$_SESSION['receipt']=$contract;return ['id'=>$contract,'reference'=>$snapshot['reference'],'is_demo'=>$snapshot['is_demo'],'holder_pending'=>$snapshot['bank']&&!$snapshot['bank']['holder_same']];});}
    public function cancelDraft():array{$this->kiosk();$this->sql('DELETE FROM drafts WHERE session_hash=?',[$this->sessionHash()]);unset($_SESSION['draft_id'],$_SESSION['receipt']);return ['cleared'=>true];}
    public function contractList(array $r):array{$rows=$this->sql('SELECT c.id,c.reference,c.member_id,c.created_at,c.state,c.payment_method,c.monthly_cents,c.center_accepted_at,m.internal_reference,m.innux_state,m.personal_enc FROM contracts c JOIN members m ON m.id=c.member_id ORDER BY c.created_at DESC LIMIT 500');$query=strtolower(trim((string)($r['query']??'')));$out=[];foreach($rows as $row){$p=$this->open($row['personal_enc']);$name=$p['name'].' '.$p['surname'];if($query!==''&&!str_contains(strtolower($name.' '.$row['reference'].' '.$row['internal_reference']),$query))continue;if(($r['state']??'')!==''&&$row['state']!==$r['state'])continue;if(($r['from']??'')!==''&&substr($row['created_at'],0,10)<$r['from'])continue;if(($r['until']??'')!==''&&substr($row['created_at'],0,10)>$r['until'])continue;unset($row['personal_enc']);$row['name']=$name;$out[]=$row;}return $out;}
    public function contractDetail(string $id):array{$c=$this->one('SELECT * FROM contracts WHERE id=?',[$id]);ensure($c,'Contrato no encontrado.',404);$s=$this->open($c['snapshot_enc']);$m=$this->one('SELECT id,internal_reference,innux_reference,innux_number,innux_state,state FROM members WHERE id=?',[$c['member_id']]);$s['bank']=$s['bank']?['holder'=>$s['bank']['holder'],'holder_same'=>$s['bank']['holder_same'],'iban'=>'•••• '.substr($s['bank']['iban'],-4)]:null;$job=$this->one('SELECT id,state,number,error_code,updated_at FROM innux_jobs WHERE contract_id=?',[$id]);if($job&&$job['state']==='COMPLETED'){$job['number']=$m['innux_number'];$job['linked_existing']=$m['innux_state']==='VERIFIED_READ_ONLY';}return ['innux_job'=>$job,'has_photo'=>(bool)$this->one('SELECT contract_id FROM contract_photos WHERE contract_id=?',[$id]),'id'=>$id,'reference'=>$c['reference'],'state'=>$c['state'],'created_at'=>$c['created_at'],'pdf_hash'=>$c['pdf_hash'],'center_accepted_at'=>$c['center_accepted_at'],'snapshot'=>$s,'member'=>$m,'email_job'=>$this->one('SELECT state,attempts,sent_at,next_try_at,last_error FROM email_jobs WHERE contract_id=? ORDER BY created_at DESC LIMIT 1',[$id]),'mandates'=>$this->sql('SELECT a.id,a.reference,a.last_four,a.state,a.holder_same,a.replaces_id,EXISTS(SELECT 1 FROM mandate_evidence e WHERE e.mandate_id=a.id) has_evidence FROM mandates a WHERE a.contract_id=?',[$id]),'evidence'=>$this->open($c['evidence_enc'])];}
    public function document(string $id):string{if(($_SESSION['mode']??'')==='kiosk')ensure(($_SESSION['receipt']??'')===$id,'No tienes acceso a este documento.',403);else $this->staff(['admin','staff','viewer']);$c=$this->one('SELECT pdf_enc,pdf_hash FROM contracts WHERE id=?',[$id]);ensure($c,'Documento no encontrado.',404);$pdf=$this->vault->decrypt($c['pdf_enc'],'pdf');ensure(hash_equals($c['pdf_hash'],hash('sha256',$pdf)),'El documento no supera la comprobación de integridad.',500);$this->transaction(fn()=>$this->audit($this->actor(),'DOCUMENT_DOWNLOADED',$id));return $pdf;}
    public function acceptContract(string $id):array{
        return $this->transaction(function()use($id){
            $c=$this->one('SELECT * FROM contracts WHERE id=?',[$id]);
            ensure($c&&$c['state']==='SIGNED','El contrato no está disponible.');
            if(!$c['center_accepted_at']){
                if($c['previous_id']){
                    ensure(!$this->one("SELECT id FROM dues WHERE contract_id=? AND state IN ('PREPARED','EXPORTED','SENT')",[$c['previous_id']]),'Resuelve o cancela las cuotas pendientes del contrato anterior antes de aceptar la nueva versión.',409);
                    ensure(!$this->one("SELECT id FROM contracts WHERE previous_id=? AND center_accepted_at IS NOT NULL AND state='SIGNED' AND id<>?",[$c['previous_id'],$id]),'Ya existe una versión posterior aceptada. Parte de esa versión.',409);
                }
                $this->sql('UPDATE contracts SET center_accepted_at=?,center_actor=? WHERE id=?',[instant(),$this->actor(),$id]);
                $this->audit($this->actor(),'CENTER_ACCEPTED',$id,['pdf_hash'=>$c['pdf_hash']]);
                // Envío automático del contrato al cliente. Un fallo de correo nunca impide aceptar el alta.
                try{if(!$c['is_demo']&&$this->mailEnabled())$this->queueContractEmail($id);}catch(Throwable $ignored){}
            }
            return ['accepted'=>true];
        });
    }
    public function annulContract(string $id,string $reason):array{return $this->transaction(function()use($id,$reason){ensure(strlen(trim($reason))>=8,'Indica un motivo de anulación (mínimo 8 caracteres).');ensure($this->one('SELECT id FROM contracts WHERE id=?',[$id]),'Contrato no encontrado.',404);ensure(!$this->one("SELECT id FROM dues WHERE contract_id=? AND state IN ('EXPORTED','SENT')",[$id]),'Hay domiciliaciones exportadas o enviadas: registra primero su resolución bancaria.');$this->sql("UPDATE contracts SET state='CANCELLED' WHERE id=?",[$id]);$this->sql("UPDATE mandates SET state='REVOKED',revoked_at=? WHERE contract_id=?",[instant(),$id]);$this->sql("UPDATE dues SET state='CANCELLED',revision=revision+1 WHERE contract_id=? AND state='PREPARED'",[$id]);$this->audit($this->actor(),'CONTRACT_CANCELLED',$id,['reason'=>trim($reason)]);return ['cancelled'=>true];});}
    public function manualHandoff(string $member):array{$m=$this->one('SELECT * FROM members WHERE id=?',[$member]);ensure($m,'Socio no encontrado.',404);$p=$this->open($m['personal_enc']);return (new ManualInnuxAdapter())->prepare($m,$p);}
    public function markInnux(array $r):array{ensure(($r['confirmed_manual']??false)===true,'Confirma que has verificado el alta en Innux.');$ref=textField($r,'innux_reference',100);$num=textField($r,'innux_number',50);$reason=textField($r,'evidence',500);return $this->transaction(function()use($r,$ref,$num,$reason){ensure($this->one('SELECT id FROM members WHERE id=?',[$r['member_id']]),'Socio no encontrado.',404);$this->sql("UPDATE members SET innux_reference=?,innux_number=?,innux_state='MANUALLY_CONFIRMED' WHERE id=?",[$ref,$num,$r['member_id']]);$this->audit($this->actor(),'INNUX_MANUALLY_CONFIRMED',$r['member_id'],['verification_reference'=>$reason]);return ['state'=>'MANUALLY_CONFIRMED','automatic'=>false];});}
}
